/**
 * Poké Pelago (Alola) — idle island assignments.
 */

export type PokePelagoIslandId = 'abeens' | 'aphun' | 'evelup';

export const POKE_PELAGO_ISLAND_IDS: readonly PokePelagoIslandId[] = ['abeens', 'aphun', 'evelup'];

export const POKE_PELAGO = Object.freeze({
    offlineCapMs: 48 * 60 * 60 * 1000,
    /** Shards per hour at level 1 on Isle Abeens (scaled by assigned Pokémon level). */
    abeensBaseShardsPerHour: 0.20,
    /** Expected item rolls per hour on Isle Aphun (discrete rolls, not a single %). */
    aphunItemRollPerHour: 0.25,
    /** XP per hour on Isle Evelup. */
    evelupXpPerHour: 720,
    evelupUnlockMinCrystals: 6,
    /** Base Pelago XP needed for level 1 -> 2. */
    xpPerLevel: 200,
    /** Pelago XP growth factor per level (+10% per level). */
    xpGrowthPerLevel: 1.10,
    /** No hard cap — Pelago level can rise indefinitely (+8% production per level). */
    maxLevel: Number.POSITIVE_INFINITY,
    /** Pelago XP units per hour at level 1 on Isle Abeens (scaled like shards; claimed as Pelago XP). */
    abeensBaseBeansPerHour: 0.4,
    /** Prestige stones per hour at level 1 on Isle Abeens (~1 / 4 h base). */
    abeensPrestigeStonePerHour: 0.25,
    /** Extra Abeens production when assignee species appears in Alola wild pools. */
    abeensAlolaAffinityMult: 1.15,
    /**
     * @deprecated Passive assigned-isle XP removed — skill XP comes from action completions + Abeens beans on claim.
     */
    assignedIslandXpPerHour: 0,
    /** Aphun rolls without a pity-tier item before the next roll is forced rare. */
    aphunPityThreshold: 8,
    /** Weight multiplier for Aphun pool items matching assignee types. */
    aphunTypeBiasMult: 2.5,

    // ── Action bars (Melvor / AdCap feel) ──
    /** Base action duration at Pelago 1 / mastery 1 (ms). */
    baseActionIntervalMs: 4000,
    /** Floor for action duration (ms). */
    minActionIntervalMs: 1500,
    /** Interval shrink factor per global Pelago level above 1 (divisor form). */
    globalIntervalBonusPerLevel: 0.01,
    /** Interval shrink factor per island mastery level above 1 (stronger specialization). */
    masteryIntervalBonusPerLevel: 0.02,
    /** Global Pelago skill XP granted per completed action. */
    skillXpPerAction: 0.08,
    /** Island mastery XP granted per completed action on that isle. */
    masteryXpPerAction: 0.15,
    /** Base Mastery XP needed for mastery level 1 -> 2. */
    masteryXpPerLevel: 100,
    /** Island mastery XP growth factor per level (+10% per level). */
    masteryXpGrowthPerLevel: 1.10,
    /** Production bonus per mastery level above 1 on that isle (+5% → 0.05). */
    masteryProdBonusPerLevel: 0.05,
    /**
     * Visual reward-bar cycles per claimable unit (10 → bar fills at 0.1 unit).
     * Speeds up gauges ×N without changing hourly economy or claim thresholds.
     */
    rewardBarCyclesPerUnit: 10,
});

/** XP needed to advance from `level` to `level + 1` (+10% compounded per level). */
export function getPelagoXpForLevel(level: number): number {
    const lvl = Math.max(1, Math.floor(Number(level) || 1));
    return Math.round(POKE_PELAGO.xpPerLevel * Math.pow(POKE_PELAGO.xpGrowthPerLevel, lvl - 1));
}

/** Mastery XP needed to advance an island from `masteryLevel` to `masteryLevel + 1` (+10% compounded per level). */
export function getIslandMasteryXpForLevel(masteryLevel: number): number {
    const lvl = Math.max(1, Math.floor(Number(masteryLevel) || 1));
    return Math.round(POKE_PELAGO.masteryXpPerLevel * Math.pow(POKE_PELAGO.masteryXpGrowthPerLevel, lvl - 1));
}

