/**
 * @file src/lib/pokePelagoLogic.ts
 */

import { coerceStr } from './coerceStr.ts';
import {
    getIslandMasteryXpForLevel,
    getPelagoXpForLevel,
    POKE_PELAGO,
    POKE_PELAGO_APHUN_POOL,
    POKE_PELAGO_APHUN_PITY_ITEM_KEYS,
    POKE_PELAGO_ISLAND_IDS,
    type PokePelagoIslandId,
} from '../../constants/balance/pokePelago.ts';
import { ALOLA_ZONE_POKEMON } from '../../constants/balance/alolaZonePokemon.ts';
import type { CreatureData } from '../types/creature.js';
import type { PokePelagoIslandState, PokePelagoState } from '../types/game/state.js';

export type { PokePelagoIslandId };
export { getIslandMasteryXpForLevel, getPelagoXpForLevel };

let alolaEncounterSpeciesCache: Set<string> | null = null;

/** Species names that appear in Alola wild pools (any channel / hub). */
export function isAlolaEncounterSpecies(speciesName: string): boolean {
    if (!alolaEncounterSpeciesCache) {
        const names = new Set<string>();
        for (const pool of Object.values(ALOLA_ZONE_POKEMON)) {
            for (const entry of pool) {
                if (entry?.name) names.add(entry.name);
            }
        }
        alolaEncounterSpeciesCache = names;
    }
    return alolaEncounterSpeciesCache.has(String(speciesName || ''));
}

/** Abeens production mult when assignee is an Alola-pool species (else 1). */
export function getAbeensAlolaAffinityMult(creature: CreatureData | null | undefined): number {
    if (!creature?.name) return 1;
    return isAlolaEncounterSpecies(String(creature.name))
        ? POKE_PELAGO.abeensAlolaAffinityMult
        : 1;
}

/** Aphun pool item keys favored by the assignee's type(s). */
export function getAphunTypeAffinityItemKeys(
    creature: CreatureData | null | undefined,
): string[] {
    if (!creature) return [];
    const types = new Set(
        [creature.type, creature.secondaryType]
            .map((t) => String(t || '').toLowerCase())
            .filter(Boolean),
    );
    const keys = new Set<string>();
    if (types.has('fighting') || types.has('poison')) keys.add('proteine');
    if (types.has('psychic') || types.has('fairy')) keys.add('calcium');
    if (types.has('fire') || types.has('dragon')) keys.add('attaque_plus');
    if (types.has('water') || types.has('steel')) keys.add('defense_plus');
    return [...keys];
}

/** Copy of Aphun pool with affinity item weights boosted. */
export function biasAphunPool(
    pool: readonly { itemKey: string; weight: number }[],
    affinityKeys: readonly string[],
    biasMult = POKE_PELAGO.aphunTypeBiasMult,
): { itemKey: string; weight: number }[] {
    if (affinityKeys.length === 0 || !(biasMult > 1)) {
        return pool.map((e) => ({ itemKey: e.itemKey, weight: e.weight }));
    }
    const favored = new Set(affinityKeys);
    return pool.map((e) => ({
        itemKey: e.itemKey,
        weight: favored.has(e.itemKey) ? e.weight * biasMult : e.weight,
    }));
}

function emptyIslandSlot(): PokePelagoIslandState {
    return {
        assignedUid: null,
        pendingShards: 0,
        pendingXp: 0,
        pendingBeans: 0,
        pendingPrestigeStones: 0,
        pendingItems: [],
        itemProgress: 0,
        actionElapsedMs: 0,
        masteryLevel: 1,
        masteryXp: 0,
    };
}

export function createDefaultPokePelagoState(now = Date.now()): PokePelagoState {
    const islands: Record<PokePelagoIslandId, PokePelagoIslandState> = {
        abeens: emptyIslandSlot(),
        aphun: emptyIslandSlot(),
        evelup: emptyIslandSlot(),
    };
    return {
        unlocked: false,
        level: 1,
        xpTowardNextLevel: 0,
        lastTickAt: now,
        islandsUnlocked: { abeens: true, aphun: true, evelup: false },
        islands,
        beans: 0,
        aphunRollsSinceRare: 0,
        evelupUnlockSeen: false,
    };
}

export function normalizePokePelagoState(raw: unknown, now = Date.now()): PokePelagoState {
    const base = createDefaultPokePelagoState(now);
    if (!raw || typeof raw !== 'object') return base;
    const o = raw as Record<string, unknown>;
    const out = { ...base };
    out.unlocked = o.unlocked === true;
    const rawLevel = Math.max(1, Math.floor(Number(o.level) || 1));
    out.level = Number.isFinite(POKE_PELAGO.maxLevel)
        ? Math.min(POKE_PELAGO.maxLevel, rawLevel)
        : rawLevel;
    // Legacy claimsTowardNextLevel is dropped (claim-based leveling removed).
    out.xpTowardNextLevel = Math.max(0, Number(o.xpTowardNextLevel) || 0);
    const need = getPelagoXpForLevel(out.level);
    if (Number.isFinite(POKE_PELAGO.maxLevel) && out.level >= POKE_PELAGO.maxLevel) {
        out.xpTowardNextLevel = 0;
    } else if (out.xpTowardNextLevel >= need) {
        out.xpTowardNextLevel = out.xpTowardNextLevel % need;
    }
    out.lastTickAt = Number(o.lastTickAt) || now;
    out.beans = Math.max(0, Math.floor(Number(o.beans) || 0));
    out.aphunRollsSinceRare = Math.max(
        0,
        Math.min(POKE_PELAGO.aphunPityThreshold, Math.floor(Number(o.aphunRollsSinceRare) || 0)),
    );
    out.evelupUnlockSeen = o.evelupUnlockSeen === true;
    if (o.islandsUnlocked && typeof o.islandsUnlocked === 'object') {
        const iu = o.islandsUnlocked as Record<string, unknown>;
        out.islandsUnlocked = {
            abeens: iu.abeens !== false,
            aphun: iu.aphun !== false,
            evelup: iu.evelup === true,
        };
    }
    if (out.unlocked) {
        out.islandsUnlocked.aphun = true;
    }
    if (o.islands && typeof o.islands === 'object') {
        for (const id of POKE_PELAGO_ISLAND_IDS) {
            const slot = (o.islands as Record<string, unknown>)[id];
            if (!slot || typeof slot !== 'object') continue;
            const s = slot as Record<string, unknown>;
            const masteryLevel = Math.max(1, Math.floor(Number(s.masteryLevel) || 1));
            let masteryXp = Math.max(0, Number(s.masteryXp) || 0);
            const masteryNeed = getIslandMasteryXpForLevel(masteryLevel);
            if (masteryXp >= masteryNeed) {
                masteryXp = masteryXp % masteryNeed;
            }
            out.islands[id] = {
                assignedUid: s.assignedUid != null ? coerceStr(s.assignedUid, '') : null,
                pendingShards: Math.max(0, Number(s.pendingShards) || 0),
                pendingXp: Math.max(0, Number(s.pendingXp) || 0),
                pendingBeans: Math.max(0, Number(s.pendingBeans) || 0),
                pendingPrestigeStones: Math.max(0, Number(s.pendingPrestigeStones) || 0),
                pendingItems: Array.isArray(s.pendingItems)
                    ? s.pendingItems.map((it) => {
                        const row = it as Record<string, unknown>;
                        return {
                            itemKey: coerceStr(row.itemKey, ''),
                            qty: Math.max(1, Math.floor(Number(row.qty) || 1)),
                        };
                    }).filter((it) => it.itemKey)
                    : [],
                itemProgress: (() => {
                    const p = Math.max(0, Number(s.itemProgress) || 0);
                    return p >= 1 ? p % 1 : p;
                })(),
                actionElapsedMs: Math.max(0, Number(s.actionElapsedMs) || 0),
                masteryLevel,
                masteryXp,
            };
        }
    }
    return out;
}

/**
 * Copy normalized fields into an existing state object (preserve identity).
 * Snapshot/notify must not replace `game.pokePelagoState` with a new instance
 * while claim/tick still hold a reference to the live object.
 */
export function assignPokePelagoStateInPlace(
    target: PokePelagoState,
    normalized: PokePelagoState,
): PokePelagoState {
    target.unlocked = normalized.unlocked;
    target.level = normalized.level;
    target.xpTowardNextLevel = normalized.xpTowardNextLevel;
    target.lastTickAt = normalized.lastTickAt;
    target.beans = normalized.beans;
    target.aphunRollsSinceRare = normalized.aphunRollsSinceRare;
    target.evelupUnlockSeen = normalized.evelupUnlockSeen;
    target.islandsUnlocked = normalized.islandsUnlocked;
    target.islands = normalized.islands;
    return target;
}

export function isIslandUnlocked(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
    unlockedCrystalCount = 0,
): boolean {
    if (islandId === 'abeens') return true;
    if (islandId === 'aphun') {
        return state.unlocked || state.islandsUnlocked.aphun !== false;
    }
    if (islandId === 'evelup') {
        return state.islandsUnlocked.evelup || unlockedCrystalCount >= POKE_PELAGO.evelupUnlockMinCrystals;
    }
    return false;
}

export interface PokePelagoIslandRates {
    shardsPerHour: number;
    xpPerHour: number;
    itemRollPerHour: number;
    beansPerHour: number;
    prestigeStonesPerHour: number;
}

/** Creature level production bonus percent (~1% per level above 1). */
export function getAssigneeLevelBonusPercent(creatureLevel: number): number {
    const lvl = Math.max(1, Math.floor(Number(creatureLevel) || 1));
    return Math.round((lvl - 1) * 1);
}

/** Production mult from island mastery level (level 1 = 1). */
export function getIslandMasteryProdMult(masteryLevel: number): number {
    const lvl = Math.max(1, Math.floor(Number(masteryLevel) || 1));
    return 1 + (lvl - 1) * POKE_PELAGO.masteryProdBonusPerLevel;
}

/** Production bonus percent from island mastery (level 1 = 0%). */
export function getIslandMasteryBonusPercent(masteryLevel: number): number {
    const lvl = Math.max(1, Math.floor(Number(masteryLevel) || 1));
    return Math.round((lvl - 1) * POKE_PELAGO.masteryProdBonusPerLevel * 100);
}

/**
 * Action interval for an island (ms), shrunk by global Pelago level and island mastery.
 * Never below `minActionIntervalMs`.
 */
export function getIslandActionIntervalMs(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
): number {
    const slot = state.islands[islandId];
    const masteryLevel = Math.max(1, Math.floor(Number(slot?.masteryLevel) || 1));
    const globalLvl = Math.max(1, Math.floor(Number(state.level) || 1));
    const globalFactor = 1 / (1 + POKE_PELAGO.globalIntervalBonusPerLevel * (globalLvl - 1));
    const masteryFactor = 1 / (1 + POKE_PELAGO.masteryIntervalBonusPerLevel * (masteryLevel - 1));
    const raw = POKE_PELAGO.baseActionIntervalMs * globalFactor * masteryFactor;
    return Math.max(POKE_PELAGO.minActionIntervalMs, raw);
}

/** 0–1 fill of the current action bar. */
export function getIslandActionProgress(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
): number {
    const interval = getIslandActionIntervalMs(state, islandId);
    if (!(interval > 0)) return 0;
    const elapsed = Math.max(0, Number(state.islands[islandId]?.actionElapsedMs) || 0);
    return Math.min(1, elapsed / interval);
}

export function getIslandHourlyRates(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
    creature: CreatureData | null | undefined,
    unlockedCrystalCount = 0,
): PokePelagoIslandRates {
    const empty: PokePelagoIslandRates = {
        shardsPerHour: 0,
        xpPerHour: 0,
        itemRollPerHour: 0,
        beansPerHour: 0,
        prestigeStonesPerHour: 0,
    };
    if (!isIslandUnlocked(state, islandId, unlockedCrystalCount) || !creature) return empty;
    const levelMult = 1 + (state.level - 1) * 0.08;
    const masteryMult = getIslandMasteryProdMult(state.islands[islandId].masteryLevel);
    const lvl = Math.max(1, Number(creature.level) || 1);
    const lvlMult = 1 + (lvl - 1) * 0.01;
    const prod = levelMult * masteryMult * lvlMult;
    if (islandId === 'abeens') {
        const alolaMult = getAbeensAlolaAffinityMult(creature);
        return {
            shardsPerHour: POKE_PELAGO.abeensBaseShardsPerHour * prod * alolaMult,
            xpPerHour: 0,
            itemRollPerHour: 0,
            beansPerHour: POKE_PELAGO.abeensBaseBeansPerHour * prod * alolaMult,
            prestigeStonesPerHour: POKE_PELAGO.abeensPrestigeStonePerHour * prod * alolaMult,
        };
    }
    if (islandId === 'aphun') {
        return {
            shardsPerHour: 0,
            xpPerHour: 0,
            itemRollPerHour: POKE_PELAGO.aphunItemRollPerHour * prod,
            beansPerHour: 0,
            prestigeStonesPerHour: 0,
        };
    }
    if (islandId === 'evelup') {
        return {
            shardsPerHour: 0,
            xpPerHour: POKE_PELAGO.evelupXpPerHour * prod,
            itemRollPerHour: 0,
            beansPerHour: 0,
            prestigeStonesPerHour: 0,
        };
    }
    return empty;
}

/**
 * Whether an island has rewards that can actually leave pending on claim.
 * Shards/XP need a grantable assignee; beans / prestige stones / items do not.
 * @param hasAssignee When omitted, uses `!!slot.assignedUid` (callers with a
 *   creature map should pass resolvable + Evelup-not-max).
 */
export function islandHasClaimable(
    slot: PokePelagoIslandState,
    hasAssignee: boolean = !!slot.assignedUid,
): boolean {
    const creatureBoundReady = hasAssignee
        && (Math.floor(slot.pendingShards) >= 1 || Math.floor(slot.pendingXp) >= 1);
    return creatureBoundReady
        || Math.floor(slot.pendingBeans ?? 0) >= 1
        || Math.floor(slot.pendingPrestigeStones ?? 0) >= 1
        || (slot.pendingItems?.length ?? 0) > 0;
}

/** True when creature-bound pending (shards/XP) can be granted to this assignee. */
export function canGrantPelagoCreatureRewards(
    islandId: PokePelagoIslandId,
    creature: CreatureData | null | undefined,
): boolean {
    if (!creature) return false;
    if (islandId === 'evelup' && isCreatureAtMaxLevel(creature)) return false;
    return true;
}

export function countClaimablePelagoIslands(
    state: PokePelagoState,
    unlockedCrystalCount = 0,
    creaturesByUid?: Map<string, CreatureData>,
): number {
    let n = 0;
    for (const id of POKE_PELAGO_ISLAND_IDS) {
        if (!isIslandUnlocked(state, id, unlockedCrystalCount)) continue;
        const slot = state.islands[id];
        let hasAssignee = !!slot.assignedUid;
        if (creaturesByUid) {
            const creature = slot.assignedUid ? creaturesByUid.get(slot.assignedUid) : null;
            hasAssignee = canGrantPelagoCreatureRewards(id, creature);
        }
        if (islandHasClaimable(slot, hasAssignee)) n += 1;
    }
    return n;
}

function pickFromPool(
    pool: readonly { itemKey: string; weight: number }[],
    rng: () => number,
): { itemKey: string; qty: number } | null {
    const first = pool[0];
    if (!first) return null;
    const total = pool.reduce((s, e) => s + e.weight, 0);
    if (total <= 0) return { itemKey: first.itemKey, qty: 1 };
    let roll = rng() * total;
    for (const entry of pool) {
        roll -= entry.weight;
        if (roll <= 0) return { itemKey: entry.itemKey, qty: 1 };
    }
    return { itemKey: first.itemKey, qty: 1 };
}

export function isAphunPityItem(itemKey: string): boolean {
    return (POKE_PELAGO_APHUN_PITY_ITEM_KEYS as readonly string[]).includes(itemKey);
}

/**
 * Pick an Aphun item, applying pity when rolls-since-rare reaches the threshold.
 * Optional assignee biases non-pity pool weights by type affinity.
 * Mutates `state.aphunRollsSinceRare`.
 */
export function pickAphunItem(
    state: PokePelagoState,
    rng = Math.random,
    creature: CreatureData | null | undefined = null,
): { itemKey: string; qty: number } | null {
    const forcePity = state.aphunRollsSinceRare >= POKE_PELAGO.aphunPityThreshold;
    const basePool = forcePity
        ? POKE_PELAGO_APHUN_POOL.filter((e) => isAphunPityItem(e.itemKey))
        : POKE_PELAGO_APHUN_POOL;
    const pool = forcePity
        ? basePool
        : biasAphunPool(basePool, getAphunTypeAffinityItemKeys(creature));
    const item = pickFromPool(pool, rng);
    if (!item) return null;
    if (isAphunPityItem(item.itemKey)) {
        state.aphunRollsSinceRare = 0;
    } else {
        state.aphunRollsSinceRare = Math.min(
            POKE_PELAGO.aphunPityThreshold,
            Math.max(0, Math.floor(Number(state.aphunRollsSinceRare) || 0)) + 1,
        );
    }
    return item;
}

/** Apply Pelago XP toward levels. Returns whether any level-up occurred. */
export function applyPelagoXp(
    state: PokePelagoState,
    amount: number,
): { leveledUp: boolean; newLevel: number } {
    const hasCap = Number.isFinite(POKE_PELAGO.maxLevel);
    if (hasCap && state.level >= POKE_PELAGO.maxLevel) {
        state.xpTowardNextLevel = 0;
        return { leveledUp: false, newLevel: state.level };
    }
    if (!(amount > 0)) {
        return { leveledUp: false, newLevel: state.level };
    }
    state.xpTowardNextLevel = Math.max(0, Number(state.xpTowardNextLevel) || 0) + amount;
    let leveledUp = false;
    while (!hasCap || state.level < POKE_PELAGO.maxLevel) {
        const need = getPelagoXpForLevel(state.level);
        if (state.xpTowardNextLevel < need) break;
        state.xpTowardNextLevel -= need;
        state.level += 1;
        leveledUp = true;
    }
    if (hasCap && state.level >= POKE_PELAGO.maxLevel) state.xpTowardNextLevel = 0;
    return { leveledUp, newLevel: state.level };
}

/** Apply island mastery XP. Returns whether any mastery level-up occurred. */
export function applyIslandMasteryXp(
    slot: PokePelagoIslandState,
    amount: number,
): { leveledUp: boolean; newLevel: number } {
    if (!(amount > 0)) {
        return {
            leveledUp: false,
            newLevel: Math.max(1, Math.floor(Number(slot.masteryLevel) || 1)),
        };
    }
    slot.masteryLevel = Math.max(1, Math.floor(Number(slot.masteryLevel) || 1));
    slot.masteryXp = Math.max(0, Number(slot.masteryXp) || 0) + amount;
    let leveledUp = false;
    while (true) {
        const need = getIslandMasteryXpForLevel(slot.masteryLevel);
        if (slot.masteryXp < need) break;
        slot.masteryXp -= need;
        slot.masteryLevel += 1;
        leveledUp = true;
    }
    return { leveledUp, newLevel: slot.masteryLevel };
}

function grantIslandActionRewards(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
    slot: PokePelagoIslandState,
    creature: CreatureData,
    actionHours: number,
    rng: () => number,
): void {
    if (!(actionHours > 0)) return;
    const levelMult = 1 + (state.level - 1) * 0.08;
    const masteryMult = getIslandMasteryProdMult(slot.masteryLevel);
    const lvl = Math.max(1, Number(creature.level) || 1);
    const lvlMult = 1 + (lvl - 1) * 0.01;
    const prod = actionHours * levelMult * masteryMult * lvlMult;

    if (islandId === 'abeens') {
        const alolaMult = getAbeensAlolaAffinityMult(creature);
        const scaled = prod * alolaMult;
        slot.pendingShards += POKE_PELAGO.abeensBaseShardsPerHour * scaled;
        slot.pendingBeans += POKE_PELAGO.abeensBaseBeansPerHour * scaled;
        slot.pendingPrestigeStones = (slot.pendingPrestigeStones ?? 0)
            + POKE_PELAGO.abeensPrestigeStonePerHour * scaled;
    } else if (islandId === 'aphun') {
        const rollRate = POKE_PELAGO.aphunItemRollPerHour * levelMult * masteryMult * lvlMult;
        // Deterministic accumulator: at 100% progress, grant one item (pity/pool RNG unchanged).
        slot.itemProgress = Math.max(0, Number(slot.itemProgress) || 0) + actionHours * rollRate;
        let safety = 0;
        while (slot.itemProgress >= 1 - 1e-12 && safety < 10_000) {
            safety += 1;
            slot.itemProgress -= 1;
            const item = pickAphunItem(state, rng, creature);
            if (!item) continue;
            const existing = slot.pendingItems.find((p) => p.itemKey === item.itemKey);
            if (existing) existing.qty += item.qty;
            else slot.pendingItems.push({ ...item });
        }
        if (slot.itemProgress < 0) slot.itemProgress = 0;
    } else if (islandId === 'evelup') {
        slot.pendingXp += POKE_PELAGO.evelupXpPerHour * prod;
    }
}

export function tickPokePelagoState(
    state: PokePelagoState,
    deltaMs: number,
    creaturesByUid: Map<string, CreatureData>,
    unlockedCrystalCount = 0,
    rng = Math.random,
): { leveledUp: boolean; newLevel: number } {
    if (!state.unlocked || deltaMs <= 0) {
        return { leveledUp: false, newLevel: state.level };
    }
    let leveledUp = false;
    let newLevel = state.level;
    const CHUNK = 64;

    for (const islandId of POKE_PELAGO_ISLAND_IDS) {
        if (!isIslandUnlocked(state, islandId, unlockedCrystalCount)) continue;
        const slot = state.islands[islandId];
        const uid = slot.assignedUid;
        if (!uid) continue;
        const creature = creaturesByUid.get(uid);
        if (!creature) continue;
        // Evelup stops producing once the assignee is at max level.
        if (islandId === 'evelup' && isCreatureAtMaxLevel(creature)) continue;

        slot.actionElapsedMs = Math.max(0, Number(slot.actionElapsedMs) || 0) + deltaMs;
        let safety = 0;
        const maxChunks = Math.ceil(deltaMs / POKE_PELAGO.minActionIntervalMs / CHUNK) + 8;

        while (safety < maxChunks) {
            safety += 1;
            const interval = getIslandActionIntervalMs(state, islandId);
            if (!(interval > 0) || slot.actionElapsedMs < interval) break;

            const rawCompletions = Math.floor(slot.actionElapsedMs / interval);
            const completions = Math.min(CHUNK, rawCompletions);
            slot.actionElapsedMs -= completions * interval;

            const actionHours = (completions * interval) / (60 * 60 * 1000);
            grantIslandActionRewards(state, islandId, slot, creature, actionHours, rng);
            applyIslandMasteryXp(slot, POKE_PELAGO.masteryXpPerAction * completions);
            const xpResult = applyPelagoXp(state, POKE_PELAGO.skillXpPerAction * completions);
            if (xpResult.leveledUp) {
                leveledUp = true;
                newLevel = xpResult.newLevel;
            }
        }
    }

    return { leveledUp, newLevel };
}

export function canAssignToPelagoIsland(
    islandId: PokePelagoIslandId,
    creature: CreatureData | null | undefined,
): boolean {
    if (!creature) return true;
    if (islandId === 'evelup' && isCreatureAtMaxLevel(creature)) return false;
    return true;
}

export function assignPokePelagoIsland(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
    uid: string | null,
    unlockedCrystalCount = 0,
    creature: CreatureData | null | undefined = null,
): boolean {
    if (!isIslandUnlocked(state, islandId, unlockedCrystalCount)) return false;
    if (uid && !canAssignToPelagoIsland(islandId, creature)) return false;
    state.islands[islandId].assignedUid = uid;
    return true;
}

export function collectPokePelagoIsland(
    state: PokePelagoState,
    islandId: PokePelagoIslandId,
): {
    shards: number;
    xp: number;
    beans: number;
    prestigeStones: number;
    items: { itemKey: string; qty: number }[];
} {
    const slot = state.islands[islandId];
    const shards = Math.floor(slot.pendingShards);
    const xp = Math.floor(slot.pendingXp);
    const beans = Math.floor(slot.pendingBeans ?? 0);
    const prestigeStones = Math.floor(slot.pendingPrestigeStones ?? 0);
    const items = slot.pendingItems.map((i) => ({ ...i }));
    slot.pendingShards -= shards;
    slot.pendingXp -= xp;
    slot.pendingBeans = Math.max(0, (slot.pendingBeans ?? 0) - beans);
    slot.pendingPrestigeStones = Math.max(0, (slot.pendingPrestigeStones ?? 0) - prestigeStones);
    slot.pendingItems = [];
    return { shards, xp, beans, prestigeStones, items };
}

export function countAssignedPelagoSlots(state: PokePelagoState): number {
    return POKE_PELAGO_ISLAND_IDS.filter((id) => !!state.islands[id].assignedUid).length;
}

/** Clear island assignments whose UID no longer exists in the creature map. */
export function clearGhostPelagoAssignees(
    state: PokePelagoState,
    creaturesByUid: Map<string, CreatureData>,
): boolean {
    let cleared = false;
    for (const id of POKE_PELAGO_ISLAND_IDS) {
        const uid = state.islands[id].assignedUid;
        if (!uid) continue;
        if (!creaturesByUid.has(uid)) {
            state.islands[id].assignedUid = null;
            cleared = true;
        }
    }
    return cleared;
}

/**
 * Ms until the next whole claimable unit (or 0 if already claimable).
 * Aphun: expected time to next item roll when idle.
 */
export function estimateIslandEtaMs(
    islandId: PokePelagoIslandId,
    slot: PokePelagoIslandState,
    rates: PokePelagoIslandRates,
    _state?: PokePelagoState,
): number | null {
    if (islandHasClaimable(slot)) return 0;

    const etaToNextUnitMs = (pending: number, ratePerHour: number): number => {
        if (!(ratePerHour > 0)) return Infinity;
        const p = Math.max(0, Number(pending) || 0);
        const into = p % 1;
        const rem = into < 1e-12 ? 1 : 1 - into;
        return (rem / ratePerHour) * 60 * 60 * 1000;
    };

    if (islandId === 'abeens') {
        if (rates.shardsPerHour <= 0 && rates.beansPerHour <= 0 && rates.prestigeStonesPerHour <= 0) {
            return null;
        }
        const eta = Math.min(
            etaToNextUnitMs(slot.pendingShards, rates.shardsPerHour),
            etaToNextUnitMs(slot.pendingBeans ?? 0, rates.beansPerHour),
            etaToNextUnitMs(slot.pendingPrestigeStones ?? 0, rates.prestigeStonesPerHour),
        );
        return Number.isFinite(eta) ? eta : null;
    }
    if (islandId === 'evelup') {
        if (rates.xpPerHour <= 0) return null;
        return etaToNextUnitMs(slot.pendingXp, rates.xpPerHour);
    }
    if (islandId === 'aphun') {
        if (rates.itemRollPerHour <= 0) return null;
        const progress = Math.min(1, Math.max(0, Number(slot.itemProgress) || 0));
        const rem = progress >= 1 - 1e-12 ? 1 : 1 - progress;
        return (rem / rates.itemRollPerHour) * 60 * 60 * 1000;
    }
    return null;
}

/**
 * @deprecated Visual fill now uses {@link rewardBarClaimFraction} (linear per claim unit).
 * Kept for tests / legacy callers — micro-cycles are no longer the Pelago bar render path.
 */
export function rewardBarCycleFill(pending: number): number {
    const p = Math.max(0, Number(pending) || 0);
    const n = Math.max(1, POKE_PELAGO.rewardBarCyclesPerUnit);
    const scaled = p * n;
    let frac = scaled % 1;
    if (frac < 0) frac += 1;
    // Exact cycle boundaries and values extremely close to 1 wrap to 0 (never freeze full).
    if (frac < 1e-12 || frac > 1 - 1e-12) return 0;
    return Math.min(1, Math.max(0, frac));
}

/** Whole claimable units stacked in pending (for UI stack counter). */
export function rewardBarStack(pending: number): number {
    return Math.max(0, Math.floor(Number(pending) || 0));
}

/**
 * 0–1 progress toward the next whole claimable unit (`pending % 1`).
 * Matches the claim threshold (`floor(pending) >= 1`).
 */
export function rewardBarClaimFraction(pending: number): number {
    const p = Math.max(0, Number(pending) || 0);
    const frac = p % 1;
    return Math.min(1, Math.max(0, frac < 1e-12 ? 0 : frac));
}

/** Display string for progress toward the next claimable unit (honest vs claim gate). */
export function rewardBarClaimDisplay(pending: number, digits = 2): string {
    return rewardBarClaimFraction(pending).toFixed(digits);
}

/** Display string for the current micro-cycle progress (visual fill only). */
export function rewardBarCycleDisplay(pending: number, digits = 2): string {
    return rewardBarCycleFill(pending).toFixed(digits);
}

/**
 * Cap client-side pending prediction so labels cannot invent an extra claimable stack
 * before the authoritative snapshot catches up.
 */
export function capPelagoPredictedPending(snapshotPending: number, predicted: number): number {
    const base = Math.max(0, Number(snapshotPending) || 0);
    const pred = Math.max(0, Number(predicted) || 0);
    const maxAllowed = Math.floor(base) + (1 - 1e-9);
    return Math.min(pred, maxAllowed);
}

/** Offline-cap shard yield estimate for Abeens at given hourly rate. */
export function estimateAbeensOfflineShards(shardsPerHour: number): number {
    if (shardsPerHour <= 0) return 0;
    const hours = POKE_PELAGO.offlineCapMs / (60 * 60 * 1000);
    return shardsPerHour * hours;
}

/** Production bonus percent from Pelago level (level 1 = 0%). */
export function getPelagoLevelBonusPercent(level: number): number {
    const lvl = Math.max(1, Math.floor(Number(level) || 1));
    return Math.round((lvl - 1) * 8);
}

/** Plafond mon : getMaxLevel() ou formule prestige (100 + p×10). */
export function isCreatureAtMaxLevel(creature: CreatureData | null | undefined): boolean {
    if (!creature) return false;
    const withMethods = creature as CreatureData & {
        isAtMaxLevel?: () => boolean;
        getMaxLevel?: () => number;
    };
    if (typeof withMethods.isAtMaxLevel === 'function') {
        return withMethods.isAtMaxLevel();
    }
    const max = typeof withMethods.getMaxLevel === 'function'
        ? withMethods.getMaxLevel()
        : 100 + (Math.max(0, Math.floor(Number(creature.prestige) || 0)) * 10);
    return Math.max(1, Number(creature.level) || 1) >= max;
}

/** Mark Evelup unlock announcement as seen; returns true if this is the first time. */
export function markEvelupUnlockSeen(state: PokePelagoState): boolean {
    if (state.evelupUnlockSeen) return false;
    state.evelupUnlockSeen = true;
    return true;
}

/**
 * Header entry visibility — region-agnostic once unlocked (same pattern as Miltank Farm).
 * Region was previously gated to Alola in the UI only; production ticks never required it.
 */
export function isPokePelagoHeaderVisible(
    unlocked: boolean,
    featureFlag = false,
): boolean {
    return !!(unlocked || featureFlag);
}
